PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'operator', active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ingredients(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, stock REAL NOT NULL DEFAULT 0, min_stock REAL NOT NULL DEFAULT 0, base_cost REAL NOT NULL DEFAULT 0, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,doc TEXT);
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,doc TEXT);
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,ingredient_id INTEGER NOT NULL,qty REAL NOT NULL,total REAL NOT NULL,supplier_id INTEGER,unit_cost REAL NOT NULL,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ingredient_id) REFERENCES ingredients(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,yield_qty REAL NOT NULL DEFAULT 1,price REAL NOT NULL DEFAULT 0,pack_cost REAL NOT NULL DEFAULT 0,other_cost REAL NOT NULL DEFAULT 0,waste_pct REAL NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS recipe_items(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,ingredient_id INTEGER NOT NULL,qty REAL NOT NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(ingredient_id) REFERENCES ingredients(id));
CREATE TABLE IF NOT EXISTS production_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,date TEXT NOT NULL,product_id INTEGER NOT NULL,qty REAL NOT NULL,status TEXT NOT NULL DEFAULT 'PLANNED',unit_cost REAL DEFAULT 0,total_cost REAL DEFAULT 0,created_by INTEGER,completed_at TEXT,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS production_cost_trace(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,ingredient_id INTEGER NOT NULL,qty_used REAL NOT NULL,unit_cost_snapshot REAL NOT NULL,total_cost REAL NOT NULL,FOREIGN KEY(order_id) REFERENCES production_orders(id),FOREIGN KEY(ingredient_id) REFERENCES ingredients(id));
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,ingredient_id INTEGER NOT NULL,type TEXT NOT NULL,qty REAL NOT NULL,ref_type TEXT,ref_id INTEGER,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ingredient_id) REFERENCES ingredients(id));
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,product_id INTEGER NOT NULL,qty REAL NOT NULL,unit_price REAL NOT NULL,total REAL NOT NULL,payment_method TEXT NOT NULL,client_id INTEGER,unit_cost_snapshot REAL NOT NULL,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(client_id) REFERENCES clients(id));
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,concept TEXT NOT NULL,type TEXT NOT NULL,amount REAL NOT NULL,payment_method TEXT NOT NULL,created_by INTEGER);
CREATE TABLE IF NOT EXISTS cash_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,account TEXT NOT NULL,type TEXT NOT NULL,concept TEXT NOT NULL,amount REAL NOT NULL,ref_type TEXT,ref_id INTEGER,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
